SQL_DOC.P_SQL:
DECLARE
V_COUNT NUMBER;
BEGIN
V_COUNT := 0;
SELECT COUNT(*) INTO V_COUNT FROM BOL_PO_KEP_INVOICE WHERE PLANT = $PLANT$ AND REQUNO = $REQUNO$ AND INVOICE_NO = $INVOICE_NO$ AND INVOICE_SEQ = $INVOICE_SEQ$ AND BUYER_ITEM_NO = $BUYER_ITEM_NO$ ;
IF V_COUNT=0 THEN
INSERT INTO BOL_PO_KEP_INVOICE( PLANT , REQUNO , INVOICE_NO , INVOICE_SEQ , BUYER_ITEM_NO , STATUS , LEGACY_PO_NO , LEGACY_PO_SEQ , PURCHASE_NO , ADD_DATE , UNIT_PRICE , ITEM_QTY , ITEM_AMT , LEGACY_PR_NO , REMARK , ADVANCE_FLAG , IF_DATE , IF_TIME , DELIV_YN , DELIV_DATE , DELIV_NAME , DELIV_TEL )VALUES( $PLANT$ , $REQUNO$ , $INVOICE_NO$ , $INVOICE_SEQ$ , $BUYER_ITEM_NO$ , $STATUS$ , $LEGACY_PO_NO$ , $LEGACY_PO_SEQ$ , $PURCHASE_NO$ , $ADD_DATE$ , $UNIT_PRICE$ , $ITEM_QTY$ , $ITEM_AMT$ , $LEGACY_PR_NO$ , $REMARK$ , $ADVANCE_FLAG$ , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , $DELIV_YN$ , $DELIV_DATE$ , $DELIV_NAME$ , $DELIV_TEL$ );
ELSE
UPDATE BOL_PO_KEP_INVOICE SET DELIV_YN = $DELIV_YN$, DELIV_DATE = $DELIV_DATE$ , DELIV_NAME = $DELIV_NAME$ , DELIV_TEL = $DELIV_TEL$ , STATUS = $STATUS$ WHERE PLANT = $PLANT$ AND REQUNO = $REQUNO$ AND INVOICE_NO = $INVOICE_NO$ AND INVOICE_SEQ = $INVOICE_SEQ$ AND BUYER_ITEM_NO = $BUYER_ITEM_NO$ ;
END IF;
END;
